/**
 * Imagens de verdade (geradas pelo PyMuPDF, 8x8 pontos) e montagem de PNG para os testes das figuras das questões.
 * Os arquivos que antes eram só "assinatura + enchimento" não passam mais na conferência do servidor.
 */
import zlib from "zlib";
import { crc32 } from "../../../server/questions/imageFiles";

export const REAL_PNG = Buffer.from(
  "",
  "hex"
);
export const REAL_JPG = Buffer.from(
  "",
  "hex"
);
/** JPG em tons de cinza 5x3. */
export const REAL_JPG_GRAY = Buffer.from(
  "",
  "hex"
);

/** Monta um bloco de PNG com a soma de conferência certa. */
export function pngChunk(type: string, data: Buffer = Buffer.alloc(0)): Buffer {
  const body = Buffer.concat([Buffer.from(type, "latin1"), data]);
  const head = Buffer.alloc(4);
  head.writeUInt32BE(data.length);
  const tail = Buffer.alloc(4);
  tail.writeUInt32BE(crc32(body));
  return Buffer.concat([head, body, tail]);
}
export const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
/** Um PNG válido (cor RGB 8 bits) de largura x altura com pontos pretos. */
export function makePng(width = 4, height = 4): Buffer {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;
  const raw = Buffer.alloc((width * 3 + 1) * height);
  return Buffer.concat([PNG_SIGNATURE, pngChunk("IHDR", ihdr), pngChunk("IDAT", zlib.deflateSync(raw)), pngChunk("IEND")]);
}
